//! Static Cglunko data, extracted from the upstream JS calculators.
//!
//! Every row is generated by `script/extract-cglunko-data.mjs` from
//! `Corgan/idleon-research-optimizer`: `RandoListo2[11]` carries the 24 upgrade
//! names, `[12]` their descriptions, `[13]` their per-level bonus values and
//! `[14]` the base of their cost curve, which
//! `js/stats/systems/w5/cglunko.js` reads as `_names`, `_descs`, `_perLv` and
//! `_costB`. `UPGRADE_CATEGORIES` says which upgrades feed the drop rate.
//! Nothing is hand-typed.

use serde::Deserialize;
use std::sync::OnceLock;

const CGLUNKO_JSON: &str = include_str!("../../data/cglunko.json");

/// The upgrade tables the overview and its breakdown read.
#[derive(Debug, Deserialize)]
struct Data {
    upgrades: Vec<Upgrade>,
}

/// One upgrade: its display name, description template, the bonus one level
/// applies and the base of its cost curve.
#[derive(Debug, Deserialize)]
struct Upgrade {
    name: String,
    desc: String,
    #[serde(rename = "perLv")]
    per_lv: f64,
    #[serde(rename = "costBase")]
    cost_base: f64,
    category: String,
}

/// The extracted tables, parsed once.
fn data() -> &'static Data {
    static DATA: OnceLock<Data> = OnceLock::new();
    DATA.get_or_init(|| serde_json::from_str(CGLUNKO_JSON).expect("cglunko.json is valid"))
}

/// An upgrade's name, or the upstream's `Upgrade N` fallback.
pub fn name(index: usize) -> String {
    data()
        .upgrades
        .get(index)
        .map_or_else(|| format!("Upgrade {}", index + 1), |row| row.name.clone())
}

/// An upgrade's per-level bonus: `RandoListo2[13][index]`.
pub fn per_lv(index: usize) -> f64 {
    data().upgrades.get(index).map_or(0.0, |row| row.per_lv)
}

/// An upgrade's description template: `RandoListo2[12][index]`, with the
/// upstream's underscores read as spaces. The upstream `_fmtDesc` fills the
/// placeholders.
pub fn description(index: usize) -> String {
    data()
        .upgrades
        .get(index)
        .map_or_else(String::new, |row| row.desc.clone())
}

/// An upgrade's cost-curve base: `RandoListo2[14][index]`.
pub fn cost_base(index: usize) -> f64 {
    data().upgrades.get(index).map_or(0.0, |row| row.cost_base)
}

/// Whether the upstream `UPGRADE_CATEGORIES` row puts an upgrade in the drop
/// rate, which is every `dr-*` category.
pub fn is_dr(index: usize) -> bool {
    data()
        .upgrades
        .get(index)
        .is_some_and(|row| row.category.starts_with("dr-"))
}

/// Whether the upstream marks an upgrade as not yet available (`locked`), which
/// the priority ranking leaves out.
pub fn locked(index: usize) -> bool {
    data()
        .upgrades
        .get(index)
        .is_some_and(|row| row.category == "locked")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_extracted_table_covers_every_upgrade() {
        let data = data();
        assert_eq!(data.upgrades.len(), 24);
        assert_eq!(name(0), "Opal Find");
        assert_eq!(name(10), "Blue Collector");
        assert_eq!(name(17), "Slop Drop+");
        assert_eq!(name(23), "IDK Broh");
        // The per-level column, in the game's own order.
        let per_lv: Vec<f64> = data.upgrades.iter().map(|row| row.per_lv).collect();
        assert_eq!(
            per_lv,
            [
                1.0, 15.0, 2.0, 8.0, 3.0, 1.0, 1.0, 3.0, 1.0, 10.0, 1.0, 1.0, 25.0, 3.0, 10.0,
                100.0, 10.0, 25.0, 2.0, 1.0, 5.0, 150.0, 2.0, 1.0
            ]
        );
    }

    #[test]
    fn an_unknown_upgrade_falls_back_instead_of_panicking() {
        assert_eq!(name(24), "Upgrade 25");
        assert_eq!(per_lv(24), 0.0);
        assert_eq!(description(24), "");
        assert_eq!(cost_base(24), 0.0);
        assert!(!is_dr(24));
    }

    #[test]
    fn descriptions_cost_bases_and_categories_follow_the_game_rows() {
        assert_eq!(description(1), "Boost Drop Rate here in The Cove by {%");
        assert_eq!(description(23), "World 7 Skill 3 my man, not yet.");
        assert_eq!(cost_base(0), 7.5);
        assert_eq!(cost_base(21), 1.4);
        assert_eq!(cost_base(23), 5.0);
        assert!(locked(23));
        assert!(!locked(22));
        // The nine DR upgrades: 1, 3, 4, 10, 12, 17, 18, 21 and 22.
        let dr: Vec<usize> = (0..24).filter(|index| is_dr(*index)).collect();
        assert_eq!(dr, [1, 3, 4, 10, 12, 17, 18, 21, 22]);
    }
}
